import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"お気に入り","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/settings/favorites.md","filePath":"ja-JP/user-guide/settings/favorites.md","lastUpdated":1785993908000}'),s={name:"ja-JP/user-guide/settings/favorites.md"};function n(i,t,l,d,g,h){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="お気に入り" tabindex="-1">お気に入り <a class="header-anchor" href="#お気に入り" aria-label="Permalink to &quot;お気に入り&quot;">​</a></h1><p>よく使うフォルダー、ファイル、URL をピン留めして、いつでもワンキーでアクセスできるようにします。</p><h2 id="お気に入りの追加" tabindex="-1">お気に入りの追加 <a class="header-anchor" href="#お気に入りの追加" aria-label="Permalink to &quot;お気に入りの追加&quot;">​</a></h2><ul><li><strong>表示名</strong> — 任意。空欄のままで対象がローカルパスの場合、パスのファイル名から自動入力されます。</li><li><strong>対象パス</strong> — ローカルパス、または <code>http://</code>/<code>https://</code> の URL。</li><li><strong>フォルダーを参照</strong> / <strong>ファイルを参照</strong> ボタン — パスを入力する代わりにネイティブのピッカーを開きます。</li><li><strong>追加</strong> ボタン — パスが入力されると有効になります。</li></ul><h2 id="リストの管理" tabindex="-1">リストの管理 <a class="header-anchor" href="#リストの管理" aria-label="Permalink to &quot;リストの管理&quot;">​</a></h2><p>リスト内の各お気に入りには名前と対象パスが表示され、行ごとに次の操作があります:</p><ul><li><strong>上へ移動</strong> / <strong>下へ移動</strong> — リストの並び順を変更します。これは他の検索結果に対するお気に入りの順位にも影響します。各行は左端の 6 点ハンドルを直接ドラッグしても並べ替えられます。これは Settings 内の他のすべての並べ替え可能なリスト(結果タイプの優先順位、クイックナビゲーションの順序、サイドバーフィルターの順序、結果グリッドの列順序)で使われているのと同じドラッグ並べ替えハンドルです。</li><li><strong>編集</strong> — 項目を上のフィールドに読み込み直し、変更できるようにします。</li><li><strong>削除</strong> — 削除します。</li></ul><h2 id="検索結果への表示" tabindex="-1">検索結果への表示 <a class="header-anchor" href="#検索結果への表示" aria-label="Permalink to &quot;検索結果への表示&quot;">​</a></h2><p>一致するお気に入りは、フォルダー/パスのラベルの横に <strong>★</strong> マーカー付きで検索結果に表示され、他の検索結果と同様、表示名で検索できます(名前に漢字が含まれる場合はピンインでも検索可能)。これは Lertaro においてカスタム検索エイリアスに最も近いものです。詳しくは <a href="./../search-syntax.html#お気に入り、カスタムエイリアスではない">検索構文</a> を参照してください。</p>',9)])])}const _=a(s,[["render",n]]);ex